import 'dart:convert';import 'package:intl/intl.dart';import 'package:sqflite/sqflite.dart';import 'local_database.dart';
class AstroRepository{AstroRepository._();static final instance=AstroRepository._();
Future<String> selectedSign()async{final d=await LocalDatabase.instance.database;final r=await d.query('profile',where:'id=1');return r.isEmpty?'aries':r.first['sign'] as String;}
Future<void> setSelectedSign(String id)async{final d=await LocalDatabase.instance.database;await d.insert('profile',{'id':1,'sign':id},conflictAlgorithm:ConflictAlgorithm.replace);}
Future<String?> setting(String k)async{final d=await LocalDatabase.instance.database;final r=await d.query('settings',where:'key=?',whereArgs:[k]);return r.isEmpty?null:r.first['value'] as String;}
Future<void> setSetting(String k,String v)async{final d=await LocalDatabase.instance.database;await d.insert('settings',{'key':k,'value':v},conflictAlgorithm:ConflictAlgorithm.replace);}
Future<List<String>> enabledCategories()async{final raw=await setting('enabled_categories');if(raw==null)return ['general','love','career','wellbeing'];try{final decoded=jsonDecode(raw);if(decoded is List){final values=decoded.whereType<String>().where((v)=>['general','love','career','wellbeing'].contains(v)).toSet().toList();return values.isEmpty?['general']:values;}}catch(_){}return ['general'];}
Future<void> setEnabledCategories(List<String> values)async{final allowed=values.where((v)=>['general','love','career','wellbeing'].contains(v)).toSet().toList();await setSetting('enabled_categories',jsonEncode(allowed.isEmpty?['general']:allowed));}
Future<List<Map<String,Object?>>> saved()async=>(await LocalDatabase.instance.database).query('saved',orderBy:'id DESC');
Future<bool> isSaved(String id)async{final d=await LocalDatabase.instance.database;return (await d.query('saved',where:'id=?',whereArgs:[id])).isNotEmpty;}
Future<void> toggleSaved(Map<String,Object?> item)async{final d=await LocalDatabase.instance.database;final id=item['id'];final old=await d.query('saved',where:'id=?',whereArgs:[id]);if(old.isNotEmpty){await d.delete('saved',where:'id=?',whereArgs:[id]);}else{await d.insert('saved',item,conflictAlgorithm:ConflictAlgorithm.replace);}}
Future<List<Map<String,Object?>>> journal({String query=''})async{final d=await LocalDatabase.instance.database;return d.query('journal',where:query.trim().isEmpty?null:'body LIKE ? OR prompt LIKE ?',whereArgs:query.trim().isEmpty?null:['%$query%','%$query%'],orderBy:'day DESC,updated_at DESC');}
Future<void> saveJournal({String? id,required String body,required String prompt,List<String> tags=const[],String? mood})async{final d=await LocalDatabase.instance.database;await d.insert('journal',{'id':id??DateTime.now().microsecondsSinceEpoch.toString(),'day':DateFormat('yyyy-MM-dd').format(DateTime.now()),'body':body,'prompt':prompt,'tags':jsonEncode(tags),'mood':mood,'updated_at':DateTime.now().toUtc().toIso8601String()},conflictAlgorithm:ConflictAlgorithm.replace);}
Future<void> deleteJournal(String id)async{final d=await LocalDatabase.instance.database;await d.delete('journal',where:'id=?',whereArgs:[id]);}
Future<void> recordRead(String id)async{final d=await LocalDatabase.instance.database;await d.insert('reading_history',{'id':id,'viewed_at':DateTime.now().toUtc().toIso8601String(),'completion_state':'opened'},conflictAlgorithm:ConflictAlgorithm.replace);}
Future<List<Map<String,Object?>>> history()async=>(await LocalDatabase.instance.database).query('reading_history',orderBy:'viewed_at DESC');
Future<void> cacheContent(String path,String version,String payload)async{final d=await LocalDatabase.instance.database;await d.transaction((txn)async{await txn.insert('content_cache',{'path':path,'version':version,'payload':payload,'updated_at':DateTime.now().toUtc().toIso8601String()},conflictAlgorithm:ConflictAlgorithm.replace);});}
Future<void> activateContentBatch(String version,List<({String path,String payload})> files)async{final d=await LocalDatabase.instance.database;await d.transaction((txn)async{for(final f in files){await txn.insert('content_cache',{'path':f.path,'version':version,'payload':f.payload,'updated_at':DateTime.now().toUtc().toIso8601String()},conflictAlgorithm:ConflictAlgorithm.replace);}});}
Future<void> cacheLunarEvents(List<Map<String,dynamic>> events)async{final d=await LocalDatabase.instance.database;await d.transaction((txn)async{for(final event in events){await txn.insert('lunar_events',{'id':event['id'],'payload':jsonEncode(event)},conflictAlgorithm:ConflictAlgorithm.replace);}});}
Future<String?> cachedContent(String path)async{final d=await LocalDatabase.instance.database;final r=await d.query('content_cache',where:'path=?',whereArgs:[path]);return r.isEmpty?null:r.first['payload'] as String;}
Future<List<Map<String,Object?>>> allSettings()async=>(await LocalDatabase.instance.database).query('settings');
Future<Map<String,Object?>> exportAll()async{final d=await LocalDatabase.instance.database;return {'schema_version':1,'exported_at':DateTime.now().toUtc().toIso8601String(),'profile':{'sign':await selectedSign()},'settings':await allSettings(),'saved':await d.query('saved'),'journal':await d.query('journal'),'reading_history':await history(),'reminders':await d.query('reminders')};}
Future<void> importAll(Map<String,dynamic> data,{required bool replace})async{if(data['schema_version']!=1)throw const FormatException('Unsupported backup schema.');for(final k in ['settings','saved','journal','reading_history','reminders']){if(data[k] is! List)throw FormatException('Invalid backup section: '+k);}final d=await LocalDatabase.instance.database;await d.transaction((txn)async{if(replace){for(final t in ['settings','saved','journal','reading_history','reminders']){await txn.delete(t);}}final profile=data['profile'];if(profile is Map){final sign=profile['sign'];if(sign is! String||!['aries','taurus','gemini','cancer','leo','virgo','libra','scorpio','sagittarius','capricorn','aquarius','pisces'].contains(sign))throw const FormatException('Backup contains an invalid zodiac sign.');await txn.insert('profile',{'id':1,'sign':sign},conflictAlgorithm:ConflictAlgorithm.replace);}for(final table in ['settings','saved','journal','reading_history','reminders']){for(final raw in data[table] as List){if(raw is Map){await txn.insert(table,Map<String,Object?>.from(raw),conflictAlgorithm:ConflictAlgorithm.replace);}}}});}
Future<Map<String,int>> weeklyRecap()async{final d=await LocalDatabase.instance.database;final cutoff=DateTime.now().subtract(const Duration(days:7)).toUtc().toIso8601String();final reads=await d.query('reading_history',where:'viewed_at >= ?',whereArgs:[cutoff]);final entries=await d.query('journal',where:'day >= ?',whereArgs:[DateFormat('yyyy-MM-dd').format(DateTime.now().subtract(const Duration(days:6)))]);final days=reads.map((e)=>DateFormat('yyyy-MM-dd').format(DateTime.parse(e['viewed_at'] as String).toLocal())).toSet();return {'readings':reads.length,'journal':entries.length,'activeDays':days.length};}
Future<void> deletePersonalData()async{final d=await LocalDatabase.instance.database;await d.transaction((txn)async{for(final t in ['saved','journal','reading_history','reminders','settings']){await txn.delete(t);}await txn.update('profile',{'sign':'aries'},where:'id=1');});}}
